-- ─────────────────────────────────────────────────────────────────────────────
-- Handbook port, step 2 — 2026-10-29
--
-- Season facts live in one row (season_settings); the handbook's deadlines
-- and master timeline become milestones (the two concepts are the same
-- thing); announcements get a table. Every statement is idempotent; the seeded
-- rows are inserted once and never overwritten, so later edits in the portal
-- survive a re-run.
-- ─────────────────────────────────────────────────────────────────────────────

-- 1. Season settings ────────────────────────────────────────────────────────
create table if not exists season_settings (
  year int primary key,
  tournament_start date not null,
  tournament_end date not null,
  applications_due date,
  foundations_start date not null,
  build_start date not null,
  stabilization_start date not null,
  execution_start date not null,
  season_end date not null,
  is_current boolean not null default false,
  created_at timestamptz not null default now(),
  check (tournament_end >= tournament_start),
  check (foundations_start < build_start and build_start < stabilization_start
         and stabilization_start < execution_start and execution_start < season_end)
);
create unique index if not exists season_settings_one_current on season_settings (is_current) where is_current;

alter table season_settings enable row level security;
drop policy if exists "Anyone can read season settings" on season_settings;
create policy "Anyone can read season settings" on season_settings for select using (true);
drop policy if exists "Leadership can manage season settings" on season_settings;
create policy "Leadership can manage season settings" on season_settings
  for all using (public.is_leadership()) with check (public.is_leadership());

insert into season_settings
  (year, tournament_start, tournament_end, applications_due, foundations_start, build_start, stabilization_start, execution_start, season_end, is_current)
values
  (2027, '2027-03-25', '2027-03-28', '2026-09-30', '2026-09-01', '2026-10-15', '2026-12-01', '2027-02-01', '2027-04-11', true)
on conflict (year) do nothing;

-- 2. Milestones absorb the handbook's deadline_events ───────────────────────
alter table milestones add column if not exists legacy_id text;
create unique index if not exists milestones_legacy_id_key on milestones (legacy_id);
alter table milestones add column if not exists phase position_phase;
alter table milestones add column if not exists priority text not null default 'medium';
alter table milestones drop constraint if exists milestones_priority_check;
alter table milestones add constraint milestones_priority_check check (priority in ('low', 'medium', 'high', 'critical'));
alter table milestones add column if not exists deadline_type text not null default 'Deadline';
alter table milestones add column if not exists owner_label text not null default 'All Teams';
alter table milestones add column if not exists send_reminders boolean not null default true;
alter table milestones add column if not exists date_label text;
alter table milestones add column if not exists created_by uuid references profiles(id) on delete set null;
alter table milestones add column if not exists updated_at timestamptz not null default now();
create index if not exists milestones_target_date_idx on milestones (target_date);

drop trigger if exists milestones_updated_at on milestones;
create trigger milestones_updated_at before update on milestones
  for each row execute procedure update_updated_at();

drop policy if exists "Board can read milestones" on milestones;
create policy "Board can read milestones" on milestones for select using (public.is_board());
drop policy if exists "RD and ADs can manage milestones" on milestones;
drop policy if exists "Leadership can manage milestones" on milestones;
create policy "Leadership can manage milestones" on milestones
  for all using (public.is_leadership()) with check (public.is_leadership());

